    qo_output.weighted_body.y = 0.0;
    qo_output.weighted_body.z = 0.0;
    return;
}

// Check config parameters validity
if (!isfinite(qo_config.minimum_weight) || qo_config.minimum_weight <= 0.0 ||
    !isfinite(qo_config.minimum_separation_sine) || qo_config.minimum_separation_sine <= 0.0 || qo_config.minimum_separation_sine > 1.0 ||
