double total_weight = 0.0;
adcs_vec3_t wb_sum = {0, 0, 0};
adcs_vec3_t wr_sum = {0, 0, 0};
adcs_vec3_t bn[3];
adcs_vec3_t rn[3];
int valid_data = 1;

for (size_t i = 0; i < qo_input.count; ++i) {
    if (!isfinite(qo_input.weights[i]) || qo_input.weights[i] <= 0.0) {
        valid_data = 0;
        break;
    }
    if (!adcs_is_finite_vec3(&qo_input.body[i]) || !adcs_is_finite_vec3(&qo_input.reference[i])) {
        valid_data = 0;
        break;
    }

    adcs_status_t st_b = adcs_vec3_normalize(&qo_input.body[i], ADCS_EPS_NORM, &bn[i]);
    adcs_status_t st_r = adcs_vec3_normalize(&qo_input.reference[i], ADCS_EPS_NORM, &rn[i]);

    if (st_b != ADCS_OK || st_r != ADCS_OK) {
        valid_data = 0;
        break;
    }

    total_weight += qo_input.weights[i];

    // Accumulate weighted normals: weighted_body = sum w_i*unit(body_i)
    wb_sum = adcs_vec3_add(&wb_sum, &adcs_vec3_scale(&bn[i], qo_input.weights[i]));
    wr_sum = adcs_vec3_add(&wr_sum, &adcs_vec3_scale(&rn[i], qo_input.weights[i]));
