adcs_vec3_t cb = adcs_vec3_cross(&bn[0], &bn[1]);
double body_sep_sin = adcs_vec3_norm(&cb);

adcs_vec3_t cr = adcs_vec3_cross(&rn[0], &rn[1]);
double ref_sep_sin = adcs_vec3_norm(&cr);

